<?php
/**
 * Source-mode entry of the transitional unified `lekalo-target-php-
 * laravel` adapter (issue #241 stage 4): the exact production process
 * surface. The committed artifact `adapter.php` is generated by
 * `build.php` from the vendored pinned package releases (lekalo-php
 * and lekalo-php-laravel under `vendor/`, pinned by
 * `php-packages.lock.json`) in fixed order, which keeps shipped bytes
 * and vendored bytes in a checkable 1:1 relation. The language
 * package's own source-mode entry lives in its repository.
 */

declare(strict_types=1);

define('ADAPTER_ID', 'lekalo-target-php-laravel');
define('TARGET_TOKEN', 'php-laravel');

require __DIR__ . '/vendor/lekalo-php/src/provider.php';
require __DIR__ . '/vendor/lekalo-php/src/analyzer.php';
require __DIR__ . '/vendor/lekalo-php/src/strict-profile.php';
require __DIR__ . '/vendor/lekalo-php/src/kernel.php';
require __DIR__ . '/vendor/lekalo-php-laravel/src/native-policy.php';
require __DIR__ . '/vendor/lekalo-php-laravel/src/native-plan.php';
// The scenario map and the type generator modules (issues #56, #58):
// the kernel lazy-loads them, so the source-mode entry requires them
// explicitly to keep the same 1:1 module surface as the bundle.
require __DIR__ . '/vendor/lekalo-php/src/scenario-map.php';
require __DIR__ . '/vendor/lekalo-php-laravel/src/scenario-emit.php';
require __DIR__ . '/vendor/lekalo-php/src/type-policy.php';
require __DIR__ . '/vendor/lekalo-php/src/type-map.php';
require __DIR__ . '/vendor/lekalo-php/src/type-codec.php';
require __DIR__ . '/vendor/lekalo-php/src/type-emit.php';
require __DIR__ . '/vendor/lekalo-php/src/type-bindings.php';
// The provider-owned modules ride last (issue #241 stage 4): the
// Laravel package's registration runs at parse time, populating the
// provider registry before `main()` dispatches — the same order
// build.php's PROVIDER_MODULES keeps in the artifact.
require __DIR__ . '/vendor/lekalo-php-laravel/src/laravel-migrations.php';
require __DIR__ . '/vendor/lekalo-php-laravel/src/laravel-lint.php';
require __DIR__ . '/vendor/lekalo-php-laravel/src/laravel-provider.php';

exit(main());
